<div class="knowledge-page"><header class="page-header"><div><p class="muted"><a href="/knowledge">Knowledge Hub</a> / <?= e($note['notebook']) ?></p><h1><?= e($note['title']) ?></h1><p class="muted">Updated <?= e($note['updated_at']) ?> · <?= e(KnowledgeService::words($note['body'])) ?> words</p></div><?php if ($note['deleted_at']===null): ?><a class="btn" href="/knowledge/<?= e($note['id']) ?>/edit">Edit note</a><?php endif; ?></header><?php require ROOT.'/app/Core/views/notices.php'; ?>
<div class="knowledge-actions"><?php if ($note['deleted_at']===null): ?><form method="post" action="/knowledge/<?= e($note['id']) ?>/pin"><?= csrf_field() ?><button class="secondary"><?= $note['pinned']?'Unpin':'Pin' ?></button></form><form method="post" action="/knowledge/<?= e($note['id']) ?>/archive"><?= csrf_field() ?><button class="secondary"><?= $note['archived']?'Unarchive':'Archive' ?></button></form><form method="post" action="/knowledge/<?= e($note['id']) ?>/duplicate"><?= csrf_field() ?><button class="secondary">Duplicate</button></form><a href="/knowledge/<?= e($note['id']) ?>/export" hx-boost="false">Export .md</a><form method="post" action="/knowledge/<?= e($note['id']) ?>/trash" data-confirm="Move this note to Trash?"><?= csrf_field() ?><button class="delete">Move to Trash</button></form><?php else: ?><form method="post" action="/knowledge/<?= e($note['id']) ?>/restore"><?= csrf_field() ?><button>Restore note</button></form><?php endif; ?></div>
<article class="card knowledge-content"><div class="knowledge-tags"><?php foreach (array_filter(array_map('trim',explode(',',$note['tags']))) as $tagName): ?><a href="/knowledge?tag=<?= rawurlencode($tagName) ?>"><?= e($tagName) ?></a><?php endforeach; ?></div><div class="knowledge-body"><?= KnowledgeService::linkedBody($note['body']) ?></div></article>
<?php if ($backlinks): ?><section class="card"><h2>Linked from</h2><ul><?php foreach ($backlinks as $source): ?><li><a href="/knowledge/<?= e($source['id']) ?>"><?= e($source['title']) ?></a></li><?php endforeach; ?></ul></section><?php endif; ?></div>
